<?php require 'inc/layout.php';if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();}$ref=$_GET['ref']??'';
$o=null;if($ref&&($_SESSION['ref']??'')===$ref){$s=db()->prepare('SELECT * FROM orders WHERE ref=?');$s->execute([$ref]);$o=$s->fetch();}
$GLOBALS['hide_whatsapp_shortcuts']=$tr;$GLOBALS['seo']=['noindex'=>true];head('Order received | Skye African Supermarket');
if(!$o){echo '<main class="wrap1"><h1 class="ph1">We could not find that order</h1><a class="b1x" href="shop">Back to the shop</a></main>';foot();exit;}
$it=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$o['id']]);$it=$it->fetchAll();$bank=bank();$tr=($o['payment']??'cash')=='transfer'&&$bank;
$subs=['substitute'=>'Substitute similar items','call'=>'Call me first','none'=>'No substitutes'];
$m="New order ".$o['ref']."\nName: ".$o['name']."\nPhone: ".$o['phone']."\n".($o['method']=='delivery'?'Delivery to: '.$o['address'].', '.$o['town'].' '.$o['postcode'].' ('.$o['zone'].")\n":"Collect in store\n").'When: '.($o['slot_date']?date('D j M',strtotime($o['slot_date'])):'').', '.$o['slot_time']."\n\nItems:\n";
foreach($it as $l){$q=$l['unit']?(0+$l['qty']).' '.$l['unit']:(0+$l['qty']).' x';$m.="- $q ".$l['name'].($l['variant']?' ('.$l['variant'].')':'').' - '.money($l['line_total'])."\n";}
$m.="\nSubtotal: ".money($o['subtotal']).($o['discount']>0?"\nDiscount (".$o['promo_code']."): -".money($o['discount']):'')."\nDelivery: ".($o['method']=='delivery'?($o['zone']=='To be confirmed'?'to be confirmed':money($o['delivery_fee'])):'Collection')."\nTotal: ".money($o['total'])."\nSubstitutions: ".$subs[$o['substitution']].($o['notes']?"\nNotes: ".$o['notes']:'')."\nPayment: ".($tr?'Bank transfer. My payment receipt is attached to this message.':'Pay on collection / delivery');
$wa='https://wa.me/'.e(wa_number()).'?text='.rawurlencode($m);?>
<main class="wrap1 thx"><div class="okbox"><i>✓</i><div><h1>Thank you, <?=e(explode(' ',$o['name'])[0])?>!</h1><p>Your order <b><?=e($o['ref'])?></b> has been received. Total: <b><?=money($o['total'])?></b></p></div></div>
<?php if($o['method']=='collect'): ?><div class="wab"><b>Collect from:</b> <?=e(shop_address())?> &middot; <?=e(implode(' · ',hours_lines()))?> &middot; <a href="<?=e(maps_link())?>" target="_blank" rel="noopener">Get directions</a></div><?php endif; ?>
<?php if($tr): ?><section class="stepc"><h2><i>1</i>Pay by bank transfer</h2><p>Transfer <b><?=money($o['total'])?></b> to this account and use <b><?=e($o['ref'])?></b> as the payment reference.</p><div class="bankbox"><?=bankrows($bank)?></div></section>
<section class="stepc"><h2><i>2</i>Confirm payment and send receipt</h2><div class="wab big"><b>Make the bank transfer first.</b> If you have not paid yet, do not continue. After payment, click the button below to open WhatsApp with your order list, attach your receipt, and send the message. Your order is not confirmed until we receive and verify the receipt.</div><button class="place wa" id="paymentDone" type="button" data-whatsapp="<?=e($wa)?>" data-ref="<?=e($o['ref'])?>" data-csrf="<?=e($_SESSION['public_csrf'])?>">Payment done - continue to WhatsApp</button><p id="payerr" class="bad" role="alert"></p><script>document.getElementById("paymentDone").addEventListener("click",async function(){const b=this,e=document.getElementById("payerr");b.disabled=true;e.textContent="";try{const f=new FormData();f.append("ref",b.dataset.ref);f.append("csrf",b.dataset.csrf);const r=await fetch("api/payment-done.php",{method:"POST",body:f}),j=await r.json();if(!j.ok)throw new Error(j.error||"Could not save payment status.");window.location.href=b.dataset.whatsapp;}catch(x){e.textContent=x.message||"Please retry. WhatsApp will open after this confirmation is saved.";b.disabled=false;}});</script></section>
<?php else: ?><section class="stepc"><h2><i>1</i>Confirm on WhatsApp</h2><div class="wab big"><b>Send your order to us on WhatsApp so we can confirm it.</b> You will pay on collection or delivery.</div><a class="place wa" href="<?=$wa?>" target="_blank" rel="noopener">Send order on WhatsApp</a></section><?php endif; ?>
<div class="sum"><h2>Your order</h2><?php foreach($it as $l): ?><div class="tr"><span><?=$l['unit']?(0+$l['qty']).' '.e($l['unit']):(0+$l['qty']).' ×'?> <?=e($l['name'])?><?=$l['variant']?' ('.e($l['variant']).')':''?></span><b><?=money($l['line_total'])?></b></div><?php endforeach; ?><div class="tr big"><span>Total</span><b><?=money($o['total'])?></b></div></div><p><a href="shop">Continue shopping</a></p></main>
<?php foot();
